class ClienteData extends DataClass implements Insertable<ClienteData> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String cicloVidaRegistro;
  final String codigo;

  /// Nombre identificador del Cliente comercial — ya no `razonSocial`:
  /// esa (junto con el RFC) pertenece a Entidad fiscal (Etapa 4E.2), una
  /// entidad distinta y separada. Un Cliente comercial puede agrupar
  /// varias Entidades fiscales (ej. Sportium), así que no tiene sentido
  /// que Cliente cargue una única razón social/RFC propios.
  final String nombreComercial;

  /// Dato maestro conservado desde la Etapa 4A — sin consumidor real
  /// todavía (segmentación comercial, cotizaciones, reportes, CRM), por
  /// eso no se expone en la interfaz de la Etapa 4E.1. Se conserva en el
  /// esquema para no tener que reintroducirlo con otra migración cuando
  /// sí exista ese consumidor.
  final String? industriaId;
  final String estatus;
  final DateTime fechaAlta;
  final String? observaciones;

  /// Logotipo corporativo (Etapa 16, evolución visual) — puntero directo
  /// a `Attachment`, mismo criterio que `Empresa.logoAttachmentId`/
  /// `Empleado.fotografiaAttachmentId`: la fila también existe en
  /// `ClienteAttachment` (categoría `logo`), el puntero solo evita un
  /// join en cada fila de la lista de Clientes. Nullable: el logo es
  /// siempre opcional, con fallback de iniciales cuando no existe.
  final String? logoAttachmentId;
  const ClienteData({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.cicloVidaRegistro,
    required this.codigo,
    required this.nombreComercial,
    this.industriaId,
    required this.estatus,
    required this.fechaAlta,
    this.observaciones,
    this.logoAttachmentId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['ciclo_vida_registro'] = Variable<String>(cicloVidaRegistro);
    map['codigo'] = Variable<String>(codigo);
    map['nombre_comercial'] = Variable<String>(nombreComercial);
    if (!nullToAbsent || industriaId != null) {
      map['industria_id'] = Variable<String>(industriaId);
    }
    map['estatus'] = Variable<String>(estatus);
    map['fecha_alta'] = Variable<DateTime>(fechaAlta);
    if (!nullToAbsent || observaciones != null) {
      map['observaciones'] = Variable<String>(observaciones);
    }
    if (!nullToAbsent || logoAttachmentId != null) {
      map['logo_attachment_id'] = Variable<String>(logoAttachmentId);
    }
    return map;
  }

  ClienteCompanion toCompanion(bool nullToAbsent) {
    return ClienteCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      cicloVidaRegistro: Value(cicloVidaRegistro),
      codigo: Value(codigo),
      nombreComercial: Value(nombreComercial),
      industriaId:
          industriaId == null && nullToAbsent
              ? const Value.absent()
              : Value(industriaId),
      estatus: Value(estatus),
      fechaAlta: Value(fechaAlta),
      observaciones:
          observaciones == null && nullToAbsent
              ? const Value.absent()
              : Value(observaciones),
      logoAttachmentId:
          logoAttachmentId == null && nullToAbsent
              ? const Value.absent()
              : Value(logoAttachmentId),
    );
  }

  factory ClienteData.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return ClienteData(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      cicloVidaRegistro: serializer.fromJson<String>(json['cicloVidaRegistro']),
      codigo: serializer.fromJson<String>(json['codigo']),
