class ServicioData extends DataClass implements Insertable<ServicioData> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String cicloVidaRegistro;
  final String codigo;
  final String clienteId;
  final String nombre;
  final String tipoServicioId;

  /// Opcional desde la Etapa 4F.1 — RISEG no tiene hoy varias oficinas
  /// administrativas y no se inventa una Sucursal solo para satisfacer
  /// esta FK. Queda disponible para cuando una empresa (propia o de un
  /// escenario futuro reutilizando este sistema) sí las tenga.
  final String? sucursalAdministrativaId;
  final String estatus;
  final DateTime fechaInicio;
  final DateTime? fechaTermino;
  final int elementosAutorizados;

  /// Debe pertenecer al mismo Cliente de este Servicio — no expresable
  /// como `CHECK` (requeriría una subconsulta entre tablas); se valida
  /// en `CrearServicioUseCase`/`ActualizarServicioUseCase` y se cubre
  /// con tests.
  final String? responsableClienteContactoId;
  final String? observaciones;

  /// Opcional — Etapa 4F.2. Debe pertenecer al mismo Cliente de este
  /// Servicio (igual razón que `responsableClienteContactoId`: no
  /// expresable como `CHECK`, se valida en
  /// `AsignarEntidadFiscalAServicioUseCase`). Una Entidad fiscal
  /// archivada después de asignada no se desvincula automáticamente —
  /// el expediente solo muestra una advertencia.
  final String? entidadFiscalId;

  /// Texto libre transitorio — Etapa 4F.2. Personal/Usuario todavía no
  /// existen; cuando existan, este campo migrará a una FK real
  /// conservando el texto histórico de los Servicios ya creados (mismo
  /// criterio ya aplicado a `Empresa.representanteLegal` en la Etapa
  /// 4A). No representa todavía ningún rol específico (supervisor,
  /// coordinador, ejecutivo comercial, etc.) — es deliberadamente
  /// genérico hasta que exista ese dominio.
  final String? responsableInterno;

  /// Referencia comercial de origen — típicamente un número de
  /// cotización hoy, pero deliberadamente sin acoplarse a ese origen:
  /// puede contener referencias de CRM, propuestas u otras fuentes
  /// futuras. Texto libre, opcional.
  final String? referenciaComercial;
  final String? referenciaContractual;

  /// Sueldo/bono mensual de referencia para el personal asignado a este
  /// Servicio (Etapa 6B) — se precargan al crear una `AsignacionServicio`
  /// nueva contra este Servicio; la asignación puede capturar importes
  /// distintos por excepción individual, y un cambio posterior aquí
  /// nunca modifica retroactivamente asignaciones ya existentes
  /// (Resolución explícita de Marlon). `sueldoMensualReferenciaPersonal`
  /// debe ser `> 0` cuando se captura; `bonoMensualReferenciaPersonal`
  /// acepta `0` — mismo criterio que `Empleado.sueldoMensualAdministrativo`/
  /// `bonoMensualAdministrativo` (Etapa 6A). En centavos, nunca `real`.
  final int? sueldoMensualReferenciaPersonal;
  final int? bonoMensualReferenciaPersonal;
  const ServicioData({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.cicloVidaRegistro,
    required this.codigo,
    required this.clienteId,
    required this.nombre,
    required this.tipoServicioId,
    this.sucursalAdministrativaId,
    required this.estatus,
    required this.fechaInicio,
    this.fechaTermino,
    required this.elementosAutorizados,
    this.responsableClienteContactoId,
    this.observaciones,
    this.entidadFiscalId,
    this.responsableInterno,
    this.referenciaComercial,
    this.referenciaContractual,
    this.sueldoMensualReferenciaPersonal,
    this.bonoMensualReferenciaPersonal,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['ciclo_vida_registro'] = Variable<String>(cicloVidaRegistro);
    map['codigo'] = Variable<String>(codigo);
    map['cliente_id'] = Variable<String>(clienteId);
    map['nombre'] = Variable<String>(nombre);
    map['tipo_servicio_id'] = Variable<String>(tipoServicioId);
    if (!nullToAbsent || sucursalAdministrativaId != null) {
      map['sucursal_administrativa_id'] = Variable<String>(
