class ServicioEventualData extends DataClass
    implements Insertable<ServicioEventualData> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String cicloVidaRegistro;

  /// `EVT-000001`, vía `CodigoSecuencia` — nunca capturado a mano y
  /// nunca usado como relación: las FK siempre van por `id`.
  final String folio;
  final String nombre;
  final DateTime fechaHoraInicio;
  final DateTime fechaHoraFin;
  final String? ubicacion;
  final String? notas;
  final int importeAcordado;
  final String estatus;
  final String tipoSolicitante;

  /// Poblado sólo cuando `tipoSolicitante == cliente`. FK real: no se
  /// copia el nombre del Cliente aquí.
  final String? clienteId;

  /// Snapshot mínimo del solicitante ocasional — poblado sólo cuando
  /// `tipoSolicitante == eventual`. No crea Cliente ni EntidadFiscal.
  final String? solicitanteNombre;
  final String? solicitanteContacto;
  final String? solicitanteTelefono;
  final String? solicitanteCorreo;

  /// A quién se le factura, cuando el solicitante es un **Cliente**
  /// (schemaVersion 90). FK real a la `EntidadFiscal` que él ya tiene
  /// registrada: aquí no se recaptura razón social ni RFC, se apunta a
  /// la que es. El snapshot congelado se toma de ella al registrar el
  /// CFDI, no antes.
  ///
  /// Nullable porque un eventual sin factura no necesita receptor
  /// fiscal, y porque el histórico anterior a la v90 no lo tiene.
  final String? entidadFiscalId;

  /// Receptor fiscal de un solicitante **ocasional** (schemaVersion
  /// 90) — quien pide el servicio y a nombre de quién se factura no
  /// son el mismo dato, y asumir que sí era el hueco real: "Juan del
  /// comité" no es "Administradora Bosques S.A. de C.V.".
  ///
  /// Sigue siendo un **snapshot**, nunca un `Cliente` ni una
  /// `EntidadFiscal` permanente: facturarle una vez a alguien no lo
  /// convierte en cartera.
  final String? solicitanteRazonSocial;
  final String? solicitanteRfc;

  /// CP del domicilio fiscal — obligatorio en un CFDI 4.0 y por eso
  /// parte del mínimo, no un extra. Mismo formato que el de
  /// `Empleado.codigoPostalFiscal`, validado por el mismo
  /// `CodigoPostalFiscalValidator`.
  final String? solicitanteCodigoPostalFiscal;

  /// Independiente por completo del estado del dinero (§16 del pedido):
  /// "con factura" no significa pendiente, ni "sin factura" contado.
  /// Cómo se acordó el precio (schemaVersion 89) — `masIva`,
  /// `ivaIncluido` o `noAplica`. Reutiliza `TratamientoIva` de
  /// Comercial, nunca un enum paralelo.
  ///
  /// **Se guarda sólo este dato comercial**: subtotal, IVA y total se
  /// derivan de él y de [importeAcordado] con
  /// `calcularTotalesVentaEventual`. Guardar los tres números sería
  /// invitar a que un día no cuadren entre sí.
  ///
  /// Es independiente de [requiereFactura]: un evento sin factura puede
  /// acordarse "más IVA" igual, y uno con factura puede ser `noAplica`
  /// si la operación está exenta. Nunca se deriva uno del otro.
  ///
  /// El default reproduce el comportamiento de la schemaVersion 88, en
  /// la que [importeAcordado] era directamente el total.
  final String tratamientoIva;
  final bool requiereFactura;
  final String? motivoCancelacion;
  final String? actorUsuarioId;
  const ServicioEventualData({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.cicloVidaRegistro,
    required this.folio,
    required this.nombre,
    required this.fechaHoraInicio,
    required this.fechaHoraFin,
    this.ubicacion,
    this.notas,
    required this.importeAcordado,
    required this.estatus,
    required this.tipoSolicitante,
    this.clienteId,
    this.solicitanteNombre,
    this.solicitanteContacto,
    this.solicitanteTelefono,
    this.solicitanteCorreo,
    this.entidadFiscalId,
    this.solicitanteRazonSocial,
    this.solicitanteRfc,
    this.solicitanteCodigoPostalFiscal,
    required this.tratamientoIva,
    required this.requiereFactura,
    this.motivoCancelacion,
    this.actorUsuarioId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['ciclo_vida_registro'] = Variable<String>(cicloVidaRegistro);
    map['folio'] = Variable<String>(folio);
    map['nombre'] = Variable<String>(nombre);
    map['fecha_hora_inicio'] = Variable<DateTime>(fechaHoraInicio);
    map['fecha_hora_fin'] = Variable<DateTime>(fechaHoraFin);
    if (!nullToAbsent || ubicacion != null) {
      map['ubicacion'] = Variable<String>(ubicacion);
    }
    if (!nullToAbsent || notas != null) {
      map['notas'] = Variable<String>(notas);
    }
    map['importe_acordado'] = Variable<int>(importeAcordado);
    map['estatus'] = Variable<String>(estatus);
    map['tipo_solicitante'] = Variable<String>(tipoSolicitante);
    if (!nullToAbsent || clienteId != null) {
      map['cliente_id'] = Variable<String>(clienteId);
    }
    if (!nullToAbsent || solicitanteNombre != null) {
      map['solicitante_nombre'] = Variable<String>(solicitanteNombre);
    }
    if (!nullToAbsent || solicitanteContacto != null) {
      map['solicitante_contacto'] = Variable<String>(solicitanteContacto);
    }
    if (!nullToAbsent || solicitanteTelefono != null) {
      map['solicitante_telefono'] = Variable<String>(solicitanteTelefono);
    }
    if (!nullToAbsent || solicitanteCorreo != null) {
      map['solicitante_correo'] = Variable<String>(solicitanteCorreo);
    }
    if (!nullToAbsent || entidadFiscalId != null) {
      map['entidad_fiscal_id'] = Variable<String>(entidadFiscalId);
    }
    if (!nullToAbsent || solicitanteRazonSocial != null) {
      map['solicitante_razon_social'] = Variable<String>(
        solicitanteRazonSocial,
      );
    }
    if (!nullToAbsent || solicitanteRfc != null) {
      map['solicitante_rfc'] = Variable<String>(solicitanteRfc);
    }
    if (!nullToAbsent || solicitanteCodigoPostalFiscal != null) {
      map['solicitante_codigo_postal_fiscal'] = Variable<String>(
        solicitanteCodigoPostalFiscal,
      );
    }
    map['tratamiento_iva'] = Variable<String>(tratamientoIva);
    map['requiere_factura'] = Variable<bool>(requiereFactura);
    if (!nullToAbsent || motivoCancelacion != null) {
      map['motivo_cancelacion'] = Variable<String>(motivoCancelacion);
    }
    if (!nullToAbsent || actorUsuarioId != null) {
      map['actor_usuario_id'] = Variable<String>(actorUsuarioId);
    }
    return map;
  }

