      map['forma_pago'] = Variable<String>(formaPago);
    }
    if (!nullToAbsent || egresoId != null) {
      map['egreso_id'] = Variable<String>(egresoId);
    }
    if (!nullToAbsent || deudaId != null) {
      map['deuda_id'] = Variable<String>(deudaId);
    }
    map['eliminado'] = Variable<bool>(eliminado);
    return map;
  }

